$gruposString = $values['name_group']; // Ex: "Administradores,GP,PÚBLICO,SAS,SECONTRU_GCM"
$fuidGrupo = $values['fuid_group'];

if (strpos($gruposString, ',') !== false) {
		// Divide os grupos em array
    $gruposArray = explode(',', $gruposString);

    // Busca o nome do grupo correspondente ao FUID
		$fuidGrupo = intval($fuidGrupo); // Garante que é número
		$rs = DB::Query("SELECT name FROM app.t_groups WHERE uid = {$fuidGrupo} LIMIT 1");

		$grupoDoFuid = '';
		if ($data = $rs->fetchAssoc()) {
			 $grupoDoFuid = $data['name'];
		}

		// Verifica se o grupo do FUID está presente
		$index = array_search($grupoDoFuid, $gruposArray);

		if ($index !== false) {
			 // Remove da lista e define como o primeiro grupo
			 unset($gruposArray[$index]);
			 $gruposArray = array_values($gruposArray); // Reindexa o array
			 $primeiroGrupo = $grupoDoFuid;
		} else {
			 // Fallback: assume o primeiro grupo como default
			 $primeiroGrupo = array_shift($gruposArray);
		}

		// Atualiza os valores principais
		$values['name_group'] = $primeiroGrupo;
		$values['fuid_group'] = $fuidGrupo;

    // Agora faz insert manual para os outros grupos
    foreach ($gruposArray as $grupo) {
        $grupo = trim($grupo);

        $rs = DB::Query("SELECT uid as fuid_group FROM app.t_groups WHERE name = '".addslashes($grupo)."' LIMIT 1");
        if ($rs) {
            $row = $rs->fetchAssoc();
            if ($row) {
               $fuid_group = $row['fuid_group'];
                // Verifica se já existe na t_pack_layer (por prefixed_name e fuid_pack)
									$checkSQL = "SELECT 1 FROM app.t_pack_layer_grupo
													 WHERE fuid_group = '".db_addslashes($fuid_group)."'
													 AND fuid_pack = '".db_addslashes($values['fuid_pack'])."' LIMIT 1";

									$checkRS = db_query($checkSQL, $conn);
									$exists = db_fetch_array($checkRS);

									if ($exists) {
											echo "<script>alert('O grupo {$grupo} já possui acesso ao tema {$values['name_tema']} e ao pacote {$values['name_pack']}')</script>";
										 // Já existe, pula pro próximo
										 continue;
									}


                $insertSQL = "INSERT INTO app.t_pack_layer_grupo 
                    (name_group, fuid_group, name_pack, name_tema, fuid_pack, fuid_tema_pack) VALUES (
                    '".addslashes($grupo)."',
                    '".addslashes($fuid_group)."',
                    '".addslashes($values['name_pack'])."',
                    '".addslashes($values['name_tema'])."',
                    '".addslashes($values['fuid_pack'])."',
                    '".addslashes($values['fuid_tema_pack'])."'
                )";

                $insertResult = DB::Query($insertSQL);
                if (!$insertResult) {
                    echo "<script>alert('Erro ao inserir grupo: ".$grupo."')</script>";
                }
            }
        } else {
            echo "<script>alert('Erro na consulta para o grupo: ".$grupo."')</script>";
        }
    }
}


